<script>
(function($) {
  const itemUrl = @json(route('purchase.receipts.items.select2'));
  const unitUrl = @json(route('purchase.receipts.units.select2'));
  const categorySets = @json($catalogCategories);
  const poBased = @json($poBased);
  const poItems = @json($poCatalogItems);
  let nextIndex = {{ count($submittedLines) }}, catalogDomain = 'raw_material', catalogPage = 1, catalogHasMore = false, catalogLoading = false, searchTimer;
  let previousSupplier = String($('#receiptSupplier').val() || ''), restoringSupplier = false;
  const catalogItems = new Map();

  window.PurchaseReceiptForm = { onSupplierCreated(response) { const supplier = response?.supplier; if (!supplier?.id) return; const $supplier = $('#receiptSupplier'), text = supplier.code ? `${supplier.name} (${supplier.code})` : supplier.name; $supplier.find(`option[value="${supplier.id}"]`).remove(); restoringSupplier = true; $supplier.append(new Option(text, supplier.id, true, true)).trigger('change.select2'); restoringSupplier = false; acceptSupplierChange(String(supplier.id)); } };
  function escapeHtml(value) { return $('<div>').text(value ?? '').html(); }
  function money(value) { return (Number.isFinite(value) ? value : 0).toFixed(2); }
  function itemKey(item) { return poBased ? `po:${item.purchase_order_item_id}` : `${item.domain}:${item.id}`; }
  function lineSelector(item) { return poBased ? `.js-receipt-line[data-order-item-id="${item.purchase_order_item_id}"]` : `.js-receipt-line[data-domain="${item.domain}"][data-item-id="${item.id}"]`; }
  function applyPrecision($line, precision) { precision = Math.max(0, Math.min(6, Number.isFinite(precision) ? precision : 6)); const step = precision === 0 ? '1' : `0.${'0'.repeat(precision - 1)}1`; $line.find('.js-receipt-quantity').attr({step, min: step}); }
  function initLine($line) { const $unit = $line.find('.js-receipt-unit'); S2.init($unit, {ajax: {url: unitUrl, dataType: 'json', delay: 200, data: p => ({q: p.term || '', domain: $line.data('domain'), item_id: $line.data('itemId')}), processResults: d => ({results: d.results || []})}}); applyPrecision($line, Number($unit.data('selectedPrecision') ?? 6)); }
  function refreshState() { const count = $('#receiptLines .js-receipt-line').length; $('#receiptSelectedCount').text(count); $('#emptyReceiptCart').toggleClass('d-none', count > 0); $('#receiptLineHeader').toggleClass('d-none', count === 0); $('#clearReceiptItems').prop('disabled', count === 0); $('.po-catalog-card').each(function() { const item = catalogItems.get($(this).data('key')); if (!item) return; const selected = $(lineSelector(item)).length > 0; $(this).toggleClass('is-selected', selected).find('.po-card-add span').text(selected ? 'Added' : (poBased ? 'Receive' : 'Add')); $(this).find('.po-card-add iconify-icon').attr('icon', selected ? 'mdi:check' : 'mdi:plus'); }); }
  function recalc() { let subtotal = 0; $('#receiptLines .js-receipt-line').each(function() { const total = Number($(this).find('.js-receipt-quantity').val() || 0) * Number($(this).find('.js-receipt-rate').val() || 0); subtotal += Number.isFinite(total) ? total : 0; $(this).find('.js-receipt-line-total').text(money(total)); }); const percent = $('#receiptDiscountType').val() === 'PERCENT', value = Math.max(0, Number($('#receiptDiscountValue').val() || 0)), discount = percent ? subtotal * Math.min(value, 100) / 100 : value, tax = Math.max(0, Number($('#receiptTax').val() || 0)); $('#receiptDiscountValue').attr('max', percent ? 100 : '9999999999999999.99'); $('#receiptSubtotal').text(money(subtotal)); $('#receiptTotal').text(money(Math.max(0, subtotal - discount + tax))); refreshState(); }
  function renderCategories() { const $select = $('#receiptCatalogCategory').empty().append(new Option('All categories', '')); (categorySets[catalogDomain] || []).forEach(c => $select.append(new Option(c.name, c.id))); }
  function message(icon, title, detail) { $('#receiptCatalog').removeClass('d-none').html(`<div class="po-catalog-message"><span><iconify-icon icon="${icon}"></iconify-icon></span><strong>${escapeHtml(title)}</strong><small>${escapeHtml(detail)}</small></div>`); $('#receiptCatalogCount').text('0 found'); $('#receiptCatalogMore').addClass('d-none'); }
  function cardHtml(item) { const mapped = !poBased && item.is_mapped ? '<span class="po-mapped-badge"><iconify-icon icon="mdi:link-variant"></iconify-icon> Mapped</span>' : '', preferred = !poBased && item.is_preferred ? '<span class="po-preferred-badge"><iconify-icon icon="mdi:star"></iconify-icon> Preferred</span>' : ''; const context = poBased ? `<div class="receipt-pending-stats"><span>Ordered <b>${item.ordered_base_quantity} ${escapeHtml(item.base_unit_code)}</b></span><span>Received <b>${item.received_base_quantity} ${escapeHtml(item.base_unit_code)}</b></span><span>Pending <b>${item.pending_base_quantity} ${escapeHtml(item.base_unit_code)}</b></span></div>` : `<p>${escapeHtml(item.category_name)} · Base: ${escapeHtml(item.unit_code)}</p>${item.supplier_code ? `<small>Supplier code: ${escapeHtml(item.supplier_code)}</small>` : ''}`; return `<article class="po-catalog-card" data-key="${escapeHtml(itemKey(item))}"><div class="po-catalog-card__image"><img src="${escapeHtml(item.image_url)}" alt=""><span>${escapeHtml(item.domain_label)}</span></div><div class="po-catalog-card__content"><div class="po-card-badges">${mapped}${preferred}</div><strong title="${escapeHtml(item.name)}">${escapeHtml(item.name)}</strong><code>${escapeHtml(item.code)}</code>${context}</div><button type="button" class="po-card-add"><iconify-icon icon="mdi:plus"></iconify-icon><span>${poBased ? 'Receive' : 'Add'}</span></button></article>`; }
  function renderPoCatalog() { const search = $('#receiptCatalogSearch').val().trim().toLowerCase(), category = $('#receiptCatalogCategory').val(); const items = poItems.filter(item => item.domain === catalogDomain && (!category || String(item.category_id || '') === String(category)) && (!search || `${item.name} ${item.code}`.toLowerCase().includes(search))); catalogItems.clear(); $('#receiptCatalog').empty(); items.forEach(item => { catalogItems.set(itemKey(item), item); $('#receiptCatalog').append(cardHtml(item)); }); if (!items.length) message('mdi:package-variant-remove', 'No pending items found', 'Try another inventory type or search term.'); else $('#receiptCatalogCount').text(`${items.length} found`); refreshState(); }
  function loadDirectCatalog(append = false) { const supplierId = $('#receiptSupplier').val(); if (!supplierId) { $('#receiptSupplierGate').removeClass('d-none'); $('#receiptCatalog').addClass('d-none').empty(); $('#receiptCatalogCount').text('0 found'); return; } if (catalogLoading) return; catalogLoading = true; if (!append) { catalogPage = 1; catalogItems.clear(); $('#receiptCatalog').removeClass('d-none').html('<div class="po-catalog-loading"><span></span><span></span><span></span><span></span></div>'); } $('#receiptSupplierGate').addClass('d-none'); $.get(itemUrl, {supplier_id: supplierId, domain: catalogDomain, category_id: $('#receiptCatalogCategory').val(), q: $('#receiptCatalogSearch').val().trim(), page: catalogPage}).done(response => { const items = response.results || []; catalogHasMore = Boolean(response.pagination?.more); if (!append) $('#receiptCatalog').empty(); items.forEach(item => { catalogItems.set(itemKey(item), item); $('#receiptCatalog').append(cardHtml(item)); }); if (!$('#receiptCatalog .po-catalog-card').length) message('mdi:package-variant-remove', 'No purchasable items found', 'Try another category or search term.'); else $('#receiptCatalogCount').text(`${$('#receiptCatalog .po-catalog-card').length}${catalogHasMore ? '+' : ''} found`); $('#receiptCatalogMore').toggleClass('d-none', !catalogHasMore); refreshState(); }).fail(() => message('mdi:alert-circle-outline', 'Could not load items', 'Please refresh and try again.')).always(() => { catalogLoading = false; }); }
  function loadCatalog() { poBased ? renderPoCatalog() : loadDirectCatalog(); }
  function addItem(item) { const $existing = $(lineSelector(item)); if ($existing.length) { $existing[0].scrollIntoView({behavior: 'smooth', block: 'center'}); $existing.addClass('is-highlighted'); setTimeout(() => $existing.removeClass('is-highlighted'), 900); return; } const $line = $($('#receiptLineTemplate').html().replaceAll('__INDEX__', nextIndex++)).appendTo('#receiptLines'), itemId = Number(item.id || item.item_id); $line.attr({'data-domain': item.domain, 'data-item-id': itemId, 'data-order-item-id': item.purchase_order_item_id || ''}).data('domain', item.domain).data('itemId', itemId); $line.find('.js-receipt-order-item-id').val(item.purchase_order_item_id || ''); $line.find('.js-receipt-domain').val(item.domain); $line.find('.js-receipt-item-id').val(itemId); $line.find('.po-cart-line__type').text(item.domain_label); $line.find('.po-cart-line__name').text(`${item.name} (${item.code})`).attr('title', `${item.name} (${item.code})`); $line.find('.js-receipt-pending').text(item.pending_base_quantity ?? '0'); $line.find('.js-receipt-base-unit').text(item.base_unit_code || ''); $line.find('.receipt-line-pending').toggleClass('d-none', !item.purchase_order_item_id); const $unit = $line.find('.js-receipt-unit'), unitId = Number(item.unit_id || item.base_unit_id), unitText = item.unit_text || `${item.unit_code} - Base unit`; $unit.append(new Option(unitText, unitId, true, true)).data('selectedPrecision', item.unit_precision); $line.find('.js-receipt-quantity').val(item.quantity_input || 1); $line.find('.js-receipt-rate').val(Number(item.unit_rate || 0).toFixed(2)); initLine($line); recalc(); $line[0].scrollIntoView({behavior: 'smooth', block: 'nearest'}); }
  function clearLines() { $('#receiptLines').empty(); recalc(); }
  function acceptSupplierChange(value) { previousSupplier = String(value || ''); clearLines(); $('#receiptCatalogSearch').val(''); $('#receiptCatalogCategory').val(''); loadDirectCatalog(); }

  S2.auto($('#purchaseReceiptForm')); $('#receiptLines .js-receipt-line').each(function() { initLine($(this)); }); renderCategories(); recalc(); loadCatalog();
  $('#receiptOrder').on('change', function() { const $source = $(this), navigate = () => { const id = $source.val(); window.location.href = @json(route('purchase.receipts.create')) + (id ? `?purchase_order_id=${encodeURIComponent(id)}` : ''); }; if ($('#receiptLines .js-receipt-line').length && window.Swal) Swal.fire({icon: 'question', title: 'Change receipt source?', text: 'Current selected items will be cleared.', showCancelButton: true, confirmButtonText: 'Yes, change'}).then(result => { if (result.isConfirmed) navigate(); else $source.val(@json($order?->id ? (string) $order->id : '')).trigger('change.select2'); }); else navigate(); });
  $('#receiptSupplier').on('change', function() { if (poBased || restoringSupplier) return; const $supplier = $(this), next = String($supplier.val() || ''); if (next === previousSupplier) return; if ($('#receiptLines .js-receipt-line').length && previousSupplier && window.Swal) Swal.fire({icon: 'question', title: 'Change supplier?', text: 'Current received items will be cleared.', showCancelButton: true, confirmButtonText: 'Yes, change'}).then(result => { if (result.isConfirmed) acceptSupplierChange(next); else { restoringSupplier = true; $supplier.val(previousSupplier).trigger('change.select2'); restoringSupplier = false; } }); else acceptSupplierChange(next); });
  $('.po-domain-tab').on('click', function() { catalogDomain = $(this).data('domain'); $('.po-domain-tab').removeClass('active'); $(this).addClass('active'); renderCategories(); $('#receiptCatalogSearch').val(''); loadCatalog(); });
  $('#receiptCatalogCategory').on('change', loadCatalog); $('#receiptCatalogSearch').on('input', function() { clearTimeout(searchTimer); searchTimer = setTimeout(loadCatalog, 260); }); $('#receiptCatalogMore').on('click', function() { catalogPage++; loadDirectCatalog(true); });
  $(document).on('click', '#receiptCatalog .po-catalog-card, #receiptCatalog .po-card-add', function(event) { event.preventDefault(); event.stopPropagation(); const item = catalogItems.get($(this).closest('.po-catalog-card').data('key')); if (item) addItem(item); });
  $(document).on('click', '.js-receipt-quantity-step', function() { const $input = $(this).siblings('.js-receipt-quantity'), step = Number($input.attr('step') || 1), current = Number($input.val() || 0), decimals = (String(step).split('.')[1] || '').length; $input.val(Math.max(step, current + Number($(this).data('direction')) * step).toFixed(decimals)).trigger('input'); });
  $(document).on('click', '.btn-remove-receipt-line', function() { $(this).closest('.js-receipt-line').remove(); recalc(); }); $(document).on('input change', '.js-receipt-quantity,.js-receipt-rate,#receiptDiscountType,#receiptDiscountValue,#receiptTax', recalc);
  $('#clearReceiptItems').on('click', function() { if (!$('#receiptLines .js-receipt-line').length) return; if (window.Swal) Swal.fire({icon: 'question', title: 'Clear received items?', showCancelButton: true, confirmButtonText: 'Yes, clear', confirmButtonColor: '#dc3545'}).then(result => { if (result.isConfirmed) clearLines(); }); else if (confirm('Clear all received items?')) clearLines(); });
})(jQuery);
</script>
